const MapData = (()=>{
  const inPoly=(p,poly)=>{let o=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const xi=poly[i][0],yi=poly[i][1],xj=poly[j][0],yj=poly[j][1];if(((yi>p[1])!=(yj>p[1]))&&(p[0]<(xj-xi)*(p[1]-yi)/(yj-yi)+xi))o=!o;}return o;};
  const landImg=new Image();
  const landCanvas=document.createElement('canvas'); landCanvas.width=1536; landCanvas.height=1024;
  const landCtx=landCanvas.getContext('2d',{willReadFrequently:true});
  let landReady=false, landPixels=null;
  landImg.onload=()=>{landCtx.clearRect(0,0,1536,1024);landCtx.drawImage(landImg,0,0,1536,1024);landPixels=landCtx.getImageData(0,0,1536,1024).data;landReady=true;};
  landImg.src=LAND_MASK;
  const build=()=>{const list=[],ix={};for(const a of BUZIOS_LOCATIONS){const [id,name,type,pop,infra,val,x,y,r]=a;const raw=BUZIOS_MESH[id];const poly=raw.map(q=>[q[0],q[1]]);const t={id,name,type,pop,infra,val,poly,shape:'mesh',center:[x,y],island:false,neighbors:[]};list.push(t);ix[id]=t;} for(const [a,ns] of Object.entries(BUZIOS_LINKS)){for(const b of ns){if(ix[a]&&ix[b]){if(!ix[a].neighbors.includes(b))ix[a].neighbors.push(b);if(!ix[b].neighbors.includes(a))ix[b].neighbors.push(a);}}} return {list,ix};};
  function isLand(x,y){if(!landReady||!landPixels)return true;const px=Math.max(0,Math.min(1535,Math.round(x))),py=Math.max(0,Math.min(1023,Math.round(y)));return landPixels[(py*1536+px)*4+3]>10;}
  return {build,inPoly,isLand,landImg,get landReady(){return landReady;}};
})();

